package fr.triche.dice.logic

/** Chiffre du chronomètre : largeur (px d'une image 720 de large) et signature 20×14 (16 niveaux de gris, 0..f). */
class Glyph(val w: Int, hex: String) {
    val f = FloatArray(hex.length) { Character.digit(hex[it], 16) / 15f }
}

